insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 13, 'E se alguma mulher tem marido descrente, e ele consente em habitar com ela, não o deixe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 14, 'Porque o marido descrente é santificado pela mulher; e a mulher descrente é santificada pelo marido. Pois de outra maneira vossos filhos seriam impuros; porém agora são santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 15, 'Mas se o descrente se separar, separe-se [também] . Em tal [situação] o irmão ou a irmã não estão sujeitos à servidão; mas Deus nos chamou para a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 16, 'Porque o que tu sabes, mulher, se salvarás ao marido? Ou o que tu sabes, marido, se salvarás a mulher?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 17, 'Porém cada um ande assim como Deus lhe repartiu, cada um como o Senhor o chamou; e assim ordeno em todas as igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 18, 'É alguém chamado, estando já circunciso? Não desfaça a circuncisão. É alguém chamado estando ainda incircunciso? Não se circuncide.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 19, 'A circuncisão nada vale, e a incircuncisão nada vale; mas [o que vale] é a obediência aos mandamentos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 20, 'Cada um fique no propósito em que foi chamado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 21, 'Foste tu chamado sendo escravo? Não te preocupes com [isto] ; mas se tu podes te tornares livre, aproveita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 22, 'Porque o que foi chamado no Senhor enquanto era escravo, para o Senhor é livre; da mesma maneira também, o que foi chamado, sendo livre, se torna escravo de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 23, 'Vós fostes comprados por alto preço; [portanto] não vos façais escravos dos seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 24, 'Irmãos, cada um continue com Deus [no estado] em que foi chamado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 25, 'E quanto às virgens, não tenho mandamento do Senhor; porém eu dou [minha] opinião, dado que tenho recebido misericórdia do Senhor para que eu seja confiável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 26, 'Considero pois isto como bom, por causa da necessidade atual, que é bom à pessoa continuar assim como está.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 27, 'Estás ligado à mulher, não busques se separar. Estás livre de mulher, não busques mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 28, 'Mas se também te casares, não pecas; e se a virgem se casar, não peca. Porém os tais terão aflições na carne, que eu [gostaria] de livrá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 29, 'Porém digo isto, irmãos, porque o tempo que resta é breve; para que também os que tem mulheres, sejam como se não as tivessem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 30, 'E os que choram, como se não chorassem; e os que se alegram, como se não se alegrassem; e os que compram, como se não possuíssem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 31, 'E os que usam [das coisas] deste mundo, como se [delas] não abusassem; porque a aparência deste mundo é passageira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 32, 'E eu queria que estivésseis sem preocupações. O solteiro se preocupa com as coisas do Senhor, como irá agradar ao Senhor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 33, 'Porém o que é casado se preocupa com as coisas do mundo, como irá agradar à mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 34, 'A mulher casada e a virgem são diferentes: a que está para casar tem preocupação com as coisas do Senhor, para ser santa, tanto de corpo como de Espírito; mas a casada tem preocupação com as coisas do mundo, como irá agradar ao marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 35, 'Porém digo isto para vosso próprio proveito; não para vos enlaçar, mas para [vos guiar] ao que é decente, e servirem ao Senhor sem distração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 36, 'Mas se alguém lhe parece que indecentemente trata com sua virgem, se ela passar da idade da juventude, e assim convier se fazer, que tal faça o que quiser, não peca, casem-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 37, 'Porém o que está firme em [seu] coração, não tendo necessidade, mas tem poder sobre sua própria vontade, e isto decidiu em seu próprio coração, de guardar sua virgem, faz bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 38, 'Portanto, o que [a dá] em casamento, faz bem; mas o que não a dá em casamento, faz melhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 39, 'A mulher casada está ligada pela Lei todo o tempo em que seu marido vive; mas se seu marido morrer, fica livre para se casar com quem quiser, contanto [que seja] no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 40, 'Porém mais bem-aventurada é, se assim continuar, segundo minha opinião. E também eu penso, que tenho o Espírito de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 1, 'E quanto às coisas sacrificadas aos ídolos, sabemos que todos temos conhecimento. O conhecimento incha [de orgulho] ,mas o amor edifica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 2, 'E se alguém acha saber alguma coisa, ainda nada conhece como se deve conhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 3, 'Mas se alguém ama a Deus, o tal dele é conhecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 4, 'Portanto, quanto ao comer das coisas sacrificadas aos ídolos: sabemos que o ídolo nada é no mundo, e que não há qualquer outro Deus, a não ser um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 5, 'Porque, ainda que também haja [alguns] que se chamem deuses, seja no céu, seja na terra (como há muitos deuses e muitos senhores),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 6, 'Todavia para nós há [só] um Deus, o Pai, do qual [são] todas as coisas, e nós para ele; e um [só] Senhor Jesus Cristo, pelo qual [são] todas as coisas, e nós por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 7, 'Mas não há em todos [este] conhecimento; porém alguns até agora comem com consciência do ídolo, como se [fossem] sacrificadas aos ídolos; e sendo sua consciência fraca, fica contaminada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 8, 'Ora, a comida não nos faz agradáveis a Deus. Porque seja o que comamos, nada temos de mais; e seja o que não comamos, nada nos falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 9, 'Mas tomai cuidado para que esta vossa liberdade não seja de maneira alguma escândalo para os fracos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 10, 'Porque se alguém vir a ti, que tens [este] conhecimento, sentado [à mesa] no templo dos ídolos, não será a consciência do que é fraco induzida a comer das coisas sacrificadas aos ídolos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 11, 'E por causa de teu conhecimento, perecerá assim o irmão fraco, pelo qual Cristo morreu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 12, 'Assim que, pecando contra os irmãos e ferindo sua fraca consciência, pecais contra Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 8, 13, 'Portanto, se a comida fizer cair ao meu irmão, nunca mais comerei carne, para que eu não faça ao meu irmão cair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 1, 'Não sou eu apóstolo? Não sou livre? Não vi eu a Jesus Cristo nosso Senhor? Não sois vós minha obra no Senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 2, 'Se para os outros não sou apóstolo, ao menos para vós eu o sou; porque vós sois o selo de meu apostolado no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 3, 'Esta é a minha defesa para com os que me condenam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 4, 'Não temos nós poder de comer e de beber?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 5, 'Não temos nós direito de trazer [conosco] uma mulher irmã, como também os demais apóstolos, e os irmãos do Senhor, e Cefas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 6, 'Ou só eu, e Barnabé, não temos direito de não trabalhar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 7, 'Quem vai para a guerra a seu próprio custo? Quem planta a vinha, e não come do seu fruto? Ou quem apascenta o gado, e não come do leite do gado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 8, 'Digo eu isto segundo a lógica humana? Ou não diz a Lei também o mesmo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 9, 'Porque na Lei de Moisés está escrito: ao boi que trilha não atarás a boca. Por acaso Deus tem preocupação com os bois?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 10, 'Ou totalmente diz por nós? Porque por nós isto está escrito; porque o que lavra, com esperança deve lavrar; e o que trilha com esperança, de sua esperança [deve] ser participante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 11, 'Se nós vos semeamos as coisas espirituais, é muito que ceifemos as vossas [coisas] carnais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 12, 'Se outros são participantes deste poder sobre vós, [porque] não tanto mais nós? Mas nós não usamos deste poder; antes tudo suportamos, para não darmos impedimento algum ao Evangelho de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 13, 'Não sabeis vós, que os que administram as coisas sagradas, comem [daquilo que é] sagrado? E os que continuamente estão junto ao altar, com o altar participam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 14, 'Assim também ordenou o Senhor, aos que anunciam o Evangelho, que vivam do Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 15, 'Porém eu de nenhuma destas coisas usei; e nem isto escrevi, para que assim se faça comigo; porque melhor me seria morrer, do que esvaecer este meu orgulho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 16, 'Porque se anunciar o Evangelho, para mim não é orgulho, pois a obrigação me é imposta. E ai de mim, se não anunciar o Evangelho!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 17, 'Porque se eu faço de boa mente, tenho recompensa; mas se eu fizer de má vontade, a responsabilidade me é confiada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 18, 'Então que recompensa tenho? Que evangelizando, proponha o Evangelho de Cristo sem receber nada de volta, para não abusar do meu poder no Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 19, 'Porque, estando eu livre de todos, me fiz servo de todos, para ganhar [ainda] mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 20, 'E me fiz como judeu para os judeus, para ganhar aos judeus; como que estivesse debaixo da Lei, para os que estão debaixo da Lei, para ganhar aos que estão debaixo da Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 21, 'Ao que estão sem Lei, como se estivesse sem Lei ( [porém] não estando sem Lei para com Deus; mas para com Cristo debaixo da Lei), para ganhar os que estão sem Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 22, 'Me fiz de fraco para os fracos, para ganhar aos fracos; tudo me fiz para todos, para por todos os meios vir a salvar a alguns.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 23, 'E isto eu faço por causa do Evangelho, para que eu também dele seja participante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 24, 'Não sabeis vós que os que correm nas competições, realmente todos correm, mas somente um leva o prêmio? Correi de tal maneira, que o alcanceis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 25, 'E todo aquele que luta, tenha domínio próprio sobre tudo. Pois aqueles fazem para receber uma coroa perecível, porém nós [para] uma que não perece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 26, 'Então assim eu corro, não como [para um lugar] incerto; assim luto, não como que dando socos no ar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 9, 27, 'Em vez disso, eu subjugo meu corpo, e o reduzo à servidão, para que quando estiver pregando para os outros, eu mesmo não seja reprovado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 1, 'Ora, irmãos, eu não quero que ignoreis que todos os nossos pais estiveram debaixo da nuvem, e todos pelo mar passaram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 2, 'E todos foram batizados na nuvem e no mar em Moisés;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 3, 'E todos comeram de um mesmo alimento espiritual;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 4, 'E todos beberam de uma mesma bebida espiritual; porque bebiam da pedra espiritual que [os] seguia; e a pedra era Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 5, 'Mas da maioria deles Deus não se agradou; por isso foram deixados no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 6, 'E estas coisas nos servem de exemplos, para que não desejemos coisas ruins, como eles desejaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 7, 'E não sejais idólatras, como alguns deles [foram] ,como está escrito: O povo se sentou para comer, e para beber, e levantaram-se para se alegrarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 8, 'E não pequemos sexualmente, como alguns deles assim pecaram, e em um dia vinte e três mil caíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 9, 'E não tentemos a Cristo, como também alguns deles tentaram, e pereceram pelas serpentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 10, 'E não murmureis, como também alguns deles murmuraram, e pereceram pelo destruidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 11, 'E todas estas coisas lhes aconteceram como exemplos, e estão escritas para nosso aviso, em quem os fins dos tempos têm chegado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 12, 'Portanto, aquele que pensa estar de pé, olhe para que não caia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 13, 'Nenhuma tentação vos veio, que não fosse humana; porém Deus é fiel; que não vos deixará tentar mais do que o que podeis, antes com a tentação também dará a saída, para que a possais suportar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 14, 'Portanto, meus amados, fugi da idolatria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 15, 'Eu vos falo como que para prudentes; jugai vós [mesmos] o que eu digo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 16, 'Por acaso o copo da bênção, que nós bendizemos, não é a comunhão do sangue de Cristo? O pão que partimos, não é a comunhão do corpo de Cristo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 17, 'Porque [assim como há] um [só] pão, nós muitos somos um [só] corpo; porque todos participamos de um [só] pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 18, 'Vede a Israel segundo a carne: por acaso os que comem os sacrifícios não são participantes do altar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 19, 'Então o que eu digo? Que o ídolo é alguma coisa? Ou que o sacrifício ao ídolo seja alguma coisa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 20, 'Mas eu digo, que as coisas que os gentios sacrificam, são sacrificadas para os demônios, e não a Deus. E não quero que sejais participantes dos demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 21, 'Não podeis beber o copo do Senhor e o copo dos demônios; não podeis ser participantes da mesa do Senhor e da mesa dos demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 22, 'Por acaso [tentamos] provocar ciúmes ao Senhor? Somos nós mais fortes do que ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 23, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm; todas as coisas me são licitas, mas nem todas as coisas edificam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 24, 'Ninguém busque para si próprio, antes cada um [busque o bem] do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 25, 'De tudo o que se vende no açougue, comei, sem vos questionar por causa da consciência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 26, 'Porque a terra é do Senhor, e [também] sua plenitude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 27, 'E se alguém dos descrentes vos convidar, e quiserdes ir, comei de tudo o que for posto diante de vós, sem vos questionar por causa da consciência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 28, 'Mas se alguém vos disser: “Isto é sacrifício a ídolos”, não comais, por causa daquele que [vos] advertiu, e [por causa] da consciência. Porque a terra e sua plenitude pertencem ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 29, 'Mas digo da consciência do outro, não a tua. Por que, então, minha liberdade é julgada pela consciência do outro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 30, 'E se eu participo [da comida] pela graça, por que sou ofendido naquilo que dou graças?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 31, 'Portanto, ao comer, ou ao beber, ou ao fazer qualquer coisa, fazei tudo para a glória de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 32, 'Sede sem escândalo, nem a judeus, nem a gregos, nem à Igreja de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 10, 33, 'Assim como eu também agrado a todos em tudo, não buscando meu próprio proveito, mas sim o de muitos, para que assim possam se salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 1, 'Sede meus imitadores, assim como eu também sou de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 2, 'Eu vos louvo, irmãos, de que em tudo vos lembrais de mim, e retendes [minhas] ordens, assim como eu vos entreguei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 3, 'Mas quero que saibais, que a cabeça de todo homem é Cristo; e a cabeça da mulher é o homem; e a cabeça de Cristo é Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 4, 'Todo homem que ora ou profetiza, tendo [alguma coisa] sobre a cabeça, desonra sua própria cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 5, 'Mas toda mulher que ora ou profetiza com a cabeça descoberta, desonra sua própria cabeça; porque é o mesmo que se a tivesse raspada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 6, 'Porque se a mulher não se cobre, raspe-se também; mas se para a mulher é vergonhoso se cortar ou se raspar, que se cubra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 7, 'Porque o homem não deve cobrir a cabeça, pois é a imagem e a glória de Deus; mas a mulher é a glória do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 8, 'Porque o homem não provem da mulher, mas sim a mulher do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 9, 'Porque também o homem não foi criado por causa da mulher, mas a mulher [foi criada] por causa do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 10, 'Portanto a mulher deve ter sobre a cabeça sinal de autoridade, por causa dos anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 11, 'Porém, nem o homem é sem a mulher, nem a mulher sem o homem, no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 12, 'Porque assim como a mulher vem do homem, assim também é o homem pela mulher; porém tudo [vem] de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 13, 'Julgai-vos entre vós mesmos: é decente que a mulher ore a Deus descoberta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 14, 'Ou não vos ensina a mesma natureza, que ter cabelo longo é desonra para o homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 15, 'Mas a mulher ter cabelo longo, lhe é honra, porque os cabelos lhe são dados por cobertura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 16, 'Porém se alguém parece ser inclinado a disputas, nós não temos tal costume, nem as igrejas de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 17, 'Mas isto eu vos declaro, que não vos louvo, porque vós vos ajuntais, não para melhor, mas para pior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 18, 'Porque, em primeiro lugar, eu ouço que, quando vos ajuntais, há divisões entre vós; e em parte eu acredito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 19, 'Porque é necessário que haja diferenças de opinião entre vós, para que os que são aprovados sejam evidenciados entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 20, 'Quando, pois, vós vos reunis, não é para comer da ceia do Senhor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 21, 'Porque cada um, comendo antes, toma sua própria ceia; e um fica com fome, e outro fica bêbado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 22, 'Por acaso não tendes casas para comer e para beber? Ou desprezais a Igreja de Deus, e envergonhais os que não têm? Que vos direi? Eu vos elogiarei? Nisto eu não [vos] elogio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 23, 'Porque eu recebi do Senhor o que também vos entreguei; que o Senhor Jesus, na noite em que foi traído, tomou o pão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 24, 'E tendo dado graças, o partiu, e disse: Tomai, comei; isto é o meu corpo, que é partido por vós; fazei isto em memória de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 25, 'Semelhantemente também, depois de cear, [tomou] o copo, dizendo: Este copo é o novo Testamento em meu sangue. Fazei isto todas as vezes que [o] beberdes, em memória de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 26, 'Porque todas as vezes que comerdes deste pão, e beberdes deste copo, anunciai a morte do Senhor, até que ele venha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 27, 'Portanto quem comer deste pão, ou beber deste copo do Senhor indignamente, será culpado do corpo e do sangue do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 28, 'Portanto examine-se cada um a si mesmo, e assim coma deste pão, e beba deste copo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 29, 'Porque quem come e bebe indignamente, para si mesmo come e bebe condenação, não discernindo o corpo do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 30, 'Por esta causa há entre vós muitos fracos e doentes, e muitos que dormem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 31, 'Porque se nós julgássemos a nós mesmos, não seríamos julgados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 32, 'Mas quando somos julgados, somos repreendidos pelo Senhor; para que não sejamos condenados com o mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 33, 'Portanto, meus irmãos, quando vos ajuntardes para comer, esperai uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 11, 34, 'Porém se alguém tiver fome, coma em casa; para que não vos ajunteis para [sofrerdes] julgamento. Quanto às demais coisas, as ordenarei quando vier.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 1, 'E quanto aos [dons] espirituais, irmãos, não quero que sejais ignorantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 2, 'Vós sabeis que éreis gentios, vós vos desviáveis para os ídolos mudos, conforme éreis guiados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 3, 'Por isso eu vos deixo claro que ninguém que fala pelo Espírito de Deus chama a Jesus de maldito; e ninguém pode dizer [que] Jesus [é] o Senhor, a não ser pelo Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 4, 'E há variedade de dons, mas o Espírito é o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 5, 'E há variedade de trabalhos [na Igreja] ,mas o Senhor é o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 6, 'E há variedade de operações, mas é o mesmo Deus que opera tudo em todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 7, 'Mas a cada um é dada a manifestação do Espírito, para o que for conveniente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 8, 'Porque a um é dada, pelo Espírito, palavra de sabedoria; e a outro palavra de conhecimento, pelo mesmo Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 9, 'e a outro fé pelo mesmo Espírito; e a outro dons de curas, pelo mesmo Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 10, 'E a outro operações de milagres; e a outro profecia; e a outro o [dom de] discernir aos espíritos; e a outro variedade de línguas; e a outro interpretação de línguas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 11, 'Mas todas estas coisas [quem] opera [é] um e o mesmo Espírito, repartindo particularmente a cada um como quer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 12, 'Porque assim como o corpo é um, e tem muitos membros, e todos os membros deste único corpo, sendo muitos, compõem um só corpo; assim também é Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 13, 'Porque também todos nós somos batizados em um [só] Espírito, para um [só] corpo, quer judeus, quer gregos, quer servos, quer livres; e para todos nós foi dado de beber um [só] Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 14, 'Porque também o corpo não é um [só] membro, mas muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 15, 'Se o pé disser: Por eu não ser mão, não sou do corpo;Por isso, ele não é do corpo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 16, 'E se a orelha disser: Por eu não ser olho, não sou do corpo;Por isso, ela não é do corpo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 17, 'Se todo o corpo fosse olho, onde [estaria] o ouvido? Se [fosse] todo ouvido, onde [estaria] o olfato?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 18, 'Mas agora Deus pôs os membros no corpo, a cada qual deles como ele quis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 19, 'Porque se todos fossem um [só] membro, onde [estaria] o corpo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 20, 'Mas há agora muitos membros, porém um [só] corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 21, 'E o olho não pode dizer à mão: Não tenho necessidade de ti;Nem a cabeça aos pés: Não tenho necessidade de vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 22, 'Antes até os membros do corpo que [nos] parecem ser os mais fracos, são muito mais necessários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 23, 'E os que pensamos serem os menos honrados do corpo, a esses muito mais honramos; e os nossos mais desprezíveis têm muito mais respeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 24, 'Porém os nosso mais respeitáveis não têm [tanta] necessidade; mas [assim] Deus juntou o corpo, dando muito mais honra ao que tinha falta [dela] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 25, 'Para que não haja divisão no corpo, mas que os membros tenham igual cuidado uns com os outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 26, 'E seja que, [caso] um membro sofra, [também] os membros sofrem juntos; e [caso] um membro seja honrado, todos os membros se alegram juntos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 27, 'E vós sois o corpo de Cristo, e membros em particular.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 28, 'E Deus pôs a uns na Igreja: em primeiro lugar apóstolos, em segundo profetas, em terceiro mestres; depois milagres, dons de curas, socorros, lideranças, variedades de línguas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 29, 'Por acaso são todos apóstolos? São todos profetas? São todos mestres? São todos com dons de milagres?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 30, 'Tem todos dons de curas? Falam todos [várias] línguas? Interpretam todos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 12, 31, 'Porém desejai com zelo pelos melhores dons; e eu vos mostro um caminho ainda mais excelente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 1, 'Ainda que eu falasse as línguas dos seres humanos e dos anjos, e não tivesse amor, seria como o metal que soa, ou como o sino que retine.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 2, 'E ainda que tivesse [o dom] de profecia, e soubesse todos os mistérios, e todo o conhecimento; e ainda que tivesse toda a fé, de tal maneira que movesse os montes de lugar, e não tivesse amor, nada seria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 3, 'E ainda que eu distribuísse todos os meus bens para alimentar [aos pobres] , e ainda que entregasse meu corpo para ser queimado, e não tivesse amor, nada me aproveitaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 4, 'O amor é paciente, é bondoso; o amor não é invejoso; o amor não é orgulhoso, não é arrogante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 5, 'O amor não trata mal; não busca os próprios [interesses] , não se ira, não é rancoroso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 6, 'Não se alegra com a injustiça, mas se alegra com a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 7, 'Tudo aguenta, tudo crê, tudo espera, tudo suporta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 8, 'O amor nunca falha. Porém as profecias serão aniquiladas; as línguas acabarão, e o conhecimento será aniquilado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 9, 'Porque em parte conhecemos, e em parte profetizamos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 10, 'Mas quando vier o [que é] completo,[Ou: perfeito] então o que é em parte será aniquilado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 11, 'Quando eu era menino, falava como menino, sentia como menino, pensava como menino; mas quando me tornei homem, aniquilei as coisas de menino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 12, 'Porque agora vemos por espelho em enigma, mas então [veremos] face a face; agora conheço em parte, mas então conhecerei assim como sou conhecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 13, 13, 'E agora continuam a fé, a esperança, [e] o amor, estes três; porém o maior destes é o amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 1, 'Segui o amor, e desejai com zelo pelos [dons] espirituais; porém principalmente que profetizeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 2, 'Porque o que fala língua [estranha] , não fala aos seres humanos, mas sim a Deus; porque ninguém [o] entende, mas em espírito fala mistérios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 3, 'Mas o que profetiza, fala aos seres humanos [para] edificação, convencimento, e consolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 4, 'O que fala língua [estranha] edifica a si mesmo; mas o que profetiza edifica à igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 5, 'E eu quero que todos vós faleis línguas, porém mais [ainda] que profetizeis; porque o que profetiza é maior que o que fala línguas, a não ser que [também] interprete, para que a igreja receba edificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 6, 'E agora irmãos, se eu viesse até vos falando línguas, o que vos aproveitaria, se não vos falasse ou por revelação, ou por conhecimento, ou por profecia, ou por doutrina?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 7, 'E até as coisas inanimadas, que produzem som, seja flauta, seja harpa, se não derem distinção de sons, como saberá o que se toca com a flauta, ou com a harpa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 8, 'Porque também se a trombeta der som incerto, quem se preparará para a guerra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 9, 'Assim [mesmo] também vós, se com a língua não derdes palavra compreensível, como se entenderá o que se diz? Porque estareis falando para o ar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 10, 'Por exemplo, há tantos tipos de vozes no mundo, e nenhuma delas é muda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 11, 'Portanto, se eu não souber o propósito da voz, serei estrangeiro para o que fala, e o que fala será estrangeiro para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 12, 'Assim também vós, dado que desejais os dons espirituais, procurai [neles] abundar, para edificação da igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 13, 'Portanto, o que fala em língua [estranha] , ore para que possa interpretar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 14, 'Porque se eu orar em língua [estranha] , meu espírito ora, mas meu entendimento fica sem fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 15, 'Então é o que? Orarei com o espírito, mas também orarei com o entendimento; cantarei com o espírito, mas também cantarei com o entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 16, 'De outra maneira, se tu bendisseres com o espírito, como aquele que não tem conhecimento dirá amém por teu bendizer? Pois ele não sabe o que tu dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 17, 'Porque em verdade tu bem dás graças; mas o outro não é edificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 18, 'Graças dou a meu Deus, que mais línguas falo que todos vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 19, 'Porém eu quero [mais] falar na igreja cinco palavras com meu entendimento, para que eu também possa instruir aos outros, do que dez mil palavras em língua [estranha] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 20, 'Irmãos, não sejais meninos no entendimento, mas sede meninos na malícia, e adultos no entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 21, 'Na Lei está escrito: A este povo falarei por gente de outras línguas, e por outros lábios; e ainda assim não me ouvirão, diz o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 22, 'Então as línguas [estranhas] são por sinal, não para os que creem, mas para os que não creem; e a profecia não é para os que não creem, mas para os que creem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 23, 'Pois se toda a igreja se reunir, e todos falarem línguas [estranhas] , e entrarem alguns sem entendimento ou descrentes, não dirão que estais loucos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 24, 'Mas se todos profetizarem, e algum sem entendimento ou descrente entrar, por todos é convencido, [e] por todos é julgado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 25, 'E assim os segredos de seu coração ficam manifestos, e assim, lançando-se sobre [seu] rosto, adorará a Deus, reconhecendo publicamente que Deus está entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 26, 'Então o que há, irmãos? Quando vos reunis, tem cada um de vós salmo, tem doutrina, tem língua [estranha] , tem revelação, tem interpretação, tudo se faça para edificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 27, 'E se alguém falar em língua [estranha] , [sejam] dois, ou no máximo três, e alternando-se, e um que interprete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 28, 'Mas se não houver intérprete, cale-se na igreja, fale porém consigo mesmo, e com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 29, 'E falem dois ou três profetas, e os outros julguem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 30, 'Mas se a outro, que estiver sentada, for revelada [alguma coisa] , cale-se o primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 31, 'Porque todos vós podeis profetizar, um após o outro, para que todos aprendam, e sejam todos fortalecidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 32, 'E os espíritos dos profetas estão sujeitos aos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 33, 'Porque Deus não é de confusão, mas de paz, como em todas as igrejas dos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 34, 'Vossas mulheres fiquem caladas nas igrejas; porque não lhes é permitido falar, mas [que] estejam sujeitas, como também a Lei o diz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 35, 'E se quiserem aprender alguma coisa, perguntem a seus próprios maridos em casa; porque é impróprio as mulheres falarem na igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 36, 'Por acaso a palavra de Deus saiu de vós? Ou ela somente chegou a vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 37, 'Se alguém pensa ser profeta, ou espiritual, reconheça que as coisas que escrevo são mandamento do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 38, 'Porém se alguém ignora, que ignore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 39, 'Portanto, irmãos, desejai com zelo profetizar, e não impeçais o falar línguas [estranhas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 14, 40, 'Fazei tudo decentemente e com ordem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 1, 'Também irmãos, eu vos declaro o Evangelho, que já vos tenho anunciado, o qual também recebestes, no qual também estais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 2, 'Pelo qual também sois salvos, se retiverdes a palavra naquela maneira, em que eu vos tenho anunciado; a não ser se tenhais crido em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 3, 'Porque primeiramente vos entreguei o que também recebi, que Cristo morreu por nossos pecados, segundo as Escrituras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 4, 'E que foi sepultado, e que ressuscitou ao terceiro dia, segundo as Escrituras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 5, 'E que foi visto por Cefas, depois pelos doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 6, 'Depois foi visto de uma fez por mais de quinhentos irmãos, dos quais a maioria [ainda] vive, e também alguns já dormem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 7, 'Depois foi visto por Tiago; depois por todos os apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 8, 'E por último de todos também foi visto por mim, como que a um nascido fora do tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 9, 'Porque eu sou o menor dos apóstolos, que não sou digno de ser chamado apóstolo, porque persegui a Igreja de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 10, 'Mas pela graça de Deus sou o que sou; e sua graça [concedida] a mim não foi vã; ao invés disso trabalhei muito mais que todos eles; porém não eu, mas a graça de Deus que está comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 11, 'Portanto, seja eu, sejam eles, assim pregamos, e assim crestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 12, 'E se é pregado que Cristo ressuscitou dos mortos, como dizem alguns dentre vós, que não há ressurreição dos mortos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 13, 'E se não há ressurreição dos mortos, [então] Cristo não ressuscitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 14, 'E se Cristo não ressuscitou, então é vã nossa pregação, e vã também é vossa fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 15, 'E assim também somos encontrados como falsas testemunhas de Deus; pois testemunhamos de Deus, que ressuscitou a Cristo, ao qual [porém] não ressuscitou, se na verdade os mortos não ressuscitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 16, 'Porque se os mortos não ressuscitam, [então] Cristo também não ressuscitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 17, 'E se Cristo não ressuscitou, vossa fé é vá, [e] ainda estais em vossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 18, 'Portanto também pereceram os que dormiram em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 19, 'Se nesta vida esperamos somente em Cristo, somos os mais miseráveis de todas as pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 20, 'Mas de fato Cristo ressuscitou dos mortos, [e] foi feito as primícias dos que dormiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 21, 'Pois dado que a morte [veio] por um homem, também por um homem [veio] a ressurreição dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 22, 'Porque assim como em Adão todos morrem, assim também em Cristo todos serão vivificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 23, 'Mas cada um em sua ordem; Cristo, as primícias; depois os que são de Cristo, em sua vinda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 24, 'Depois será o fim, quando entregar o Reino de Deus e ao Pai, quando aniquilar todo domínio, e toda autoridade e poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 25, 'Porque convém que ele reine, até que tenha posto todos os inimigos debaixo de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 26, 'O último inimigo, que será aniquilado, [é] a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 27, 'Porque ele sujeitou todas as coisas debaixo de seus pés. Porém quando diz que todas as coisas [lhe] estão sujeitas, está claro que se excetua aquele que todas as coisas lhe sujeitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 28, 'E quando todas as coisas lhe forem sujeitas, então também o mesmo Filho se sujeitará a aquele, que todas as coisas lhe sujeitou, para que Deus seja tudo em todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 29, 'De outra maneira, que farão os que se batizam pelos mortos, se totalmente os mortos não ressuscitam? Por que, então, se batizam pelos mortos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 30, 'Por que também nós à toda hora estamos em perigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 31, 'A cada dia eu morro pelo orgulho que tenho por vós, em Cristo Jesus nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 32, 'Se por motivo humano lutei contra feras em Éfeso, qual é o meu proveito? Se os mortos não ressuscitam, comamos e bebamos, que amanhã morreremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 33, 'Não erreis. As más companhias corrompem os bons costumes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 34, 'Despertai para a justiça, e não pequeis; porque alguns [ainda] não têm o conhecimento de Deus. Eu digo isto para vossa vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 35, 'Mas alguém dirá: Como ressuscitarão os mortos? E com que corpo virão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 36, 'Louco, o que tu semeias não é vivificado, se [primeiro] não morrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 37, 'E o que semeias, não semeias o corpo que irá brotar, mas o grão nu, como o de trigo, ou de qualquer outro [grão] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 38, 'Mas Deus lhe dá o corpo como quer, e a cada semente seu próprio corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 39, 'Toda carne não é a mesma carne; mas uma é a carne humana, e outra a carne dos animais, e outra a dos peixes, e outra a das aves.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 40, 'E há corpos celestiais, e corpos terrestres; mas uma é a glória dos celestiais, e outra a dos terrestres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 41, 'Outra é a glória do Sol, e outra a glória da Lua, e outra a glória das estrelas; porque [uma] estrela difere em glória [de outra] estrela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 42, 'Assim também será a ressurreição dos mortos. Semeia-se [o corpo] degradável, ressuscitará capaz de nunca se degradar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 43, 'Semeia-se em desonra, ressuscitará em glória. Semeia-se em fraqueza, ressuscitará em força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 44, 'Semeia-se corpo natural, ressuscitará corpo espiritual. Há corpo animal, e há corpo espiritual.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 45, 'Assim também está escrito: O primeiro homem, Adão, foi feito em alma vivente; o último Adão em espírito vivificante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 46, 'Mas não é primeiro o espiritual; mas sim o carnal, depois o espiritual.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 47, 'O primeiro homem da terra [é] terrestre; o segundo homem, [que é] o Senhor, [é] do Céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 48, 'Assim como [é] o terrestre, também [são] os terrestres; e assim como [é] o celestial, também [são] os celestiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 49, 'E assim como trouxemos a imagem do terrestre, assim também traremos a imagem do celestial.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 50, 'Porém isto digo, irmãos, que a carne e o sangue não podem herdar o Reino de Deus, nem o que é degradável herda a capacidade de não se degradar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 51, 'eis que eu vos digo um mistério: nem todos em verdade dormiremos; porém todos seremos transformados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 52, 'Em um momento, em um piscar de olhos, à ultima trombeta; porque a trombeta soará, e os mortos ressuscitarão capazes de não se degradar, e nós seremos transformados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 53, 'Porque é necessário que este [corpo] degradável revista-se da capacidade de não se degradar, e este [corpo] mortal vista a imortalidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 54, 'E quando este [corpo] se revestir da capacidade de não se degradar, e este [corpo] mortal se vestir de imortalidade, então se cumprirá a palavra que está escrita: Na vitória, a morte é tragada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 55, 'Onde está, ó morte, o teu aguilhão? Onde está, ó Xeol, a tua vitória?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 56, 'O aguilhão da morte é o pecado, e a força do pecado é a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 57, 'Mas graças a Deus, que nos dá vitória por meio do nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 15, 58, 'Portanto, meus amados irmãos, sede firmes, imóveis [e] sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 1, 'E quanto à coleta que [se faz] para os santos, fazei também como ordenei às igrejas da Galácia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 2, 'Cada primeiro [dia] da semana, cada um de vós ponha [alguma coisa] à pate, reservando [para isso] conforme a prosperidade que tiver obtido, para que, quando eu vier, não se façam coletas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 3, 'E quando eu vier, enviarei aos que por cartas aprovardes, para que levem vossa doação para Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 4, 'E se for necessário que eu também vá, irão comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 5, 'Mas virei até vós, depois de passar pela Macedônia (porque passarei pela Macedônia).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 6, 'E pode ser que eu fique [um tempo] convosco ou também passar o inverno, para que me envieis para onde quer que eu for.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 7, 'Porque eu não quero vos ver agora [apenas] de passagem; mas espero ficar convosco por algum tempo, se o Senhor o permitir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 8, 'Porém ficarei em Éfeso até o Pentecostes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 9, 'Porque uma porta grande e eficaz se abriu para mim, e há muitos adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 10, 'E se vier Timóteo, olhai para que ele esteja sem temor convosco; porque assim como eu, ele também faz a obra do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 11, 'Portanto ninguém o despreze; mas enviai-o em paz, para que ele venha a mim; porque eu o espero com os irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 12, 'E quanto ao irmão Apolo, muito roguei que ele viesse com os irmãos até vós; mas ele de maneira nenhuma teve vontade de vir por agora; porém oferecendo-se a ele boa oportunidade, ele virá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 13, 'Vigiai, ficai firmes na fé, sede corajosos, [e] vos esforçai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 14, 'Todas as vossas coisas sejam feitas em amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 15, 'Vós sabeis que [os da] casa de Estéfanas foram os primeiros da Acaia, e que eles têm se dedicado ao trabalho dos santos; rogo-vos, pois, irmãos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 16, 'Que também vos sujeiteis a eles, e a todo aquele que opera e trabalha junto [conosco] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 17, 'E eu me alegro com a vinda de Estéfanas, e de Fortunato, e de Acaico, porque estes supriram o que de vossa [parte me] faltava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 18, 'Porque eles confortaram meu espírito, e [também] o vosso. Então reconhecei aos tais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 19, 'As igrejas da Ásia vos saúdam. Áquila e Priscila vos saúdam-vos afetuosamente no Senhor, e também a igreja que está na casa deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 20, 'Todos os irmãos vos saúdam. Saudai-vos uns as outros com beijo santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 21, 'Saudação de minha [própria] mão, de Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 22, 'Se alguém não ama ao Senhor Jesus Cristo seja anátema. Vem, Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 23, 'A graça do Senhor Jesus Cristo esteja convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 16, 24, 'Meu amor esteja com todos vós em Cristo Jesus. Amém. [A primeira Carta aos Coríntios foi escrita de Filipos, e enviada por Estéfanas, Fortunato, Acaico e Timóteo]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 1, 'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, e o irmão Timóteo, para a igreja de Deus que está em Corinto, com todos os santos que estão em toda a Acaia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 2, 'Graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai das misericórdias, e o Deus de toda consolação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 4, 'Que nos consola em toda aflição nossa, para que também possamos consolar aos que estiverem em alguma aflição, com a consolação com que nós mesmos por Deus somos consolados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 5, 'Porque assim como os sofrimentos de Cristo são abundantes em nós, assim também por Cristo é abundante nossa consolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 6, 'Porém se nós somos afligidos, é para vossa consolação e salvação, que opera enquanto se suporta os mesmos sofrimentos que nós também sofremos; se estamos consolados, [também é] para vossa consolação e salvação'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 7, 'E nossa esperança por vós é firme, sabendo que, como sois participantes dos sofrimentos, assim também [sois] da consolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 8, 'Porque, irmãos, não queremos que ignoreis nossa aflição que nos sobreveio na Ásia, em que fomos excessivamente oprimidos, mais do que podíamos suportar, de tal modo que já tínhamos perdido a esperança de sobrevivermos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 9, 'Por isso já tínhamos em nós mesmos a sentença de morte, para que não confiássemos em nós mesmos, mas sim em Deus, que ressuscita aos mortos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 10, 'O qual nos livrou de tamanha morte, e [ainda nos] livra; nele esperamos que também ainda [nos] livrará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 11, 'Junto do vosso auxílio com oração por nós, a fim de que, pelo favor [concedido] a nós por causa de muitas pessoas, por muitos sejam dadas graças [a Deus] por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 12, 'Porque nosso orgulho é este: o testemunho de nossa consciência, que com simplicidade e sinceridade de Deus, não com sabedoria carnal, mas com a graça de Deus, nós nos comportamos no mundo, e especialmente convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 13, 'Porque nenhuma outra coisa vos escrevemos, a não ser as que já sabeis, ou também entendeis; e espero que as entendereis por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 14, 'Assim como também já em parte tendes nos entendido, que somos vosso orgulho, como também vós sois o nosso [orgulho] no dia do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 15, 'E com esta confiança eu quis primeiro vir até vós, para que tivésseis uma segunda graça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 16, 'E por vós passar para a Macedônia; e da Macedônia vir outra vez até vós; e [depois] ser enviado por vós até a Judeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 17, 'Quando eu planejei isso, por acaso fiz de forma irresponsável? Ou o que eu planejo, planejo segundo a carne, para que eu diga sim e não [ao mesmo tempo] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 18, 'Porém [assim como] Deus é fiel, nossa palavra para vós não foi sim e não [ao mesmo tempo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 19, 'Porque o Filho de Deus, Jesus Cristo, o que por nós foi pregado entre vós, [isto é] , por mim, e Silvano, e Timóteo, não foi sim e não, mas nele foi o “sim”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 20, 'Porque todas as promessas nele são “sim”, e nele [se diga] Amém, para glória de Deus por meio de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 21, 'Mas o que nos confirma convosco, e o que nos ungiu, é Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 22, 'O qual também nos selou, e [nos] deu o penhor do Espírito em nosso corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 23, 'Porém invoco a Deus por testemunha sobre minha alma, que para vos poupar, até agora não vim a Corinto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 1, 24, 'Não que sejamos senhores de vossa fé; porém somos cooperadores de vossa alegria. Porque pela fé estais firmes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 1, 'Porém decidi isto mesmo comigo, de não mais vir até vós com tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 2, 'Porque se eu vos entristecer, então quem será o que me alegrará, senão aquele que por mim foi entristecido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 3, 'E isto mesmo vos escrevi, para que quando vier, não tenha tristeza dos que deveriam me alegrar, confiando de vós todos, que minha alegria é [a alegria] de todos vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 4, 'Porque em muita aflição e angústia de coração eu vos escrevi com muitas lágrimas, não para que vos entristecêsseis, mas para que entendêsseis o amor que tenho em abundância para convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 5, 'Porém se alguém [me] entristeceu, não entristeceu a mim [somente] , mas em parte (para que não se exagere) a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 6, 'Basta ao tal esta repreensão feita pela maioria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 7, 'De maneira que, ao invés disso, [deveis lhe] perdoar e consolar, para que ele não seja consumido pela excessiva tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 8, 'Por isso vos peço que confirmeis o amor para com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 9, 'Pois também para isso eu escrevi, para vos conhecer por meio de prova se vós sois obedientes em tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 10, 'E ao que perdoardes alguma coisa, também eu [lhe perdoo] ; pois a quem eu tenho perdoado, se também eu perdoei, por causa de vós [o fiz] na presença de Cristo; para que Satanás não tire proveito de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 11, 'Porque não ignoramos seus pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 12, 'Além disso, quando vim a Troas para [pregar] o Evangelho de Cristo, e abrindo-se porta para mim no Senhor, não tive repouso em meu espírito, por não achar a meu irmão Tito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 13, 'Porém, despedindo-me deles, eu parti para a Macedônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 14, 'E graças a Deus, que sempre nos faz triunfar em Cristo, e por nós em todo lugar manifesta o cheiro de seu conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 15, 'Porque para Deus somos o bom cheiro de Cristo, nos que se salvam, e nos que se perdem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 16, 'Para estes certamente cheiro de morte, para a morte; mas para aqueles cheiro de vida, para a vida. E quem é idôneo para estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 2, 17, 'Porque nós não somos como muitos, que tentam vender a palavra de Deus; mas nós [a] falamos em Cristo, diante de Deus, com sinceridade, como [enviados] de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 1, 'Por acaso começamos a recomendarmos a nós mesmos outra vez? Ou necessitamos, como alguns [necessitam] , de cartas de recomendação para vós, ou de vossa recomendação?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 2, 'Vós sois nossa carta [de recomendação] ,escrita em nossos corações, conhecida e lida por todos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 3, 'Manifestando que sois a carta de Cristo, administrada por nós, [e] escrita, não com tinta, mas com o Espírito do Deus vivente; não em tábuas de pedra, mas em tábuas de carne do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 4, 'E tal confiança temos por Cristo para com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 5, 'Não que sejamos capazes de pensar alguma coisa de nós como [se fosse] de nós mesmos, mas nossa capacidade é de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 6, 'O qual também nos fez capazes para sermos ministros do Novo Testamento, não da letra, mas do Espírito; porque a letra mata, mas o Espírito vivifica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 7, 'E se o ministério da morte em letras, impresso em pedras, foi com glória, de maneira que os filhos de Israel não podiam fixar os olhos no rosto de Moisés, por causa da glória de seu rosto, que se extinguia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 8, 'Por acaso o ministério do Espírito não terá ainda mais glória?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 9, 'Porque se o ministério da condenação teve glória, o ministério da justiça excede muito mais em glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 10, 'Pois o que já foi glorioso, em comparação, deixou de ter glória, por causa da glória superior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 11, 'Porque se o que se extinguiu teve glória, muito mais glória tem o que permanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 12, 'Visto que temos tal esperança, falamos com muita ousadia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 13, 'Não como Moisés, que punha um véu sobre o seu rosto, para que os filhos de Israel não enxergassem o fim do que se extinguia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 14, 'Porém suas mentes foram endurecidas, porque até hoje fica o mesmo véu ainda coberto na leitura do antigo pacto, o qual é extinto por Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 15, 'Mas até hoje, quando se lê [as palavras de] Moisés, o véu está posto sobre o coração deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 16, 'Porém quando se converterem ao Senhor, [então] o véu será tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 17, 'O Senhor é o Espírito; e onde está o Espírito do Senhor, aí há liberdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 3, 18, 'E todos nós, com o rosto descoberto, refletindo como que um espelho a glória do Senhor, somos transformados de glória em glória, [segundo] a mesma imagem, como pelo Espírito do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 1, 'Por isso, tendo este ministério, segundo a misericórdia que nos foi feita, não desfalecemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 2, 'Mas já rejeitamos as coisas ocultas e vergonhosas, não andando com astúcia, nem falsificando a Palavra de Deus, mas pela manifestação da verdade fazemos recomendação de nós mesmos à consciência de todos os seres humanos, à vista de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 3, 'Porém se o nosso Evangelho está encoberto, é para os que se perdem que está encoberto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 4, 'Nos quais o deus destes tempos cegou os entendimentos, [isto é] ,os incrédulos, para que não lhes brilhe a luz do Evangelho da glória de Cristo, que é a imagem de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 5, 'Porque nós não pregamos a nós mesmos, mas sim a Cristo Jesus, o Senhor; e a nós mesmos [como] vossos servos, por causa de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 6, 'Porque o Deus que disse que das trevas brilhasse a luz é o [mesmo] que brilhou em nossos corações, para a iluminação do conhecimento da glória de Deus no rosto de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 7, 'Porém temos este tesouro em vasos de barro, para que a excelência do poder seja de Deus, e não de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 8, '[Somos] em tudo afligidos, mas não esmagados; perplexos, mas não desesperados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 9, 'Perseguidos, mas não desamparados; abatidos, porém não destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 10, 'Sempre por todas as partes trazendo a mortificação do Senhor Jesus no corpo, para que também a vida de Jesus se manifeste em nossos corpos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 11, 'Porque nós, que vivemos, estamos sempre entregues à morte por causa de Jesus, para que também a vida de Jesus se manifeste em nossa carne mortal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 12, 'De maneira que a morte opera em nós, mas em vós [opera] a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 13, 'E nós temos o mesmo Espírito de fé, assim como está escrito: Cri, e por isso falei;Nós também cremos, e por isso também falamos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 14, 'sabendo que o que ressuscitou ao Senhor Jesus, também nos ressuscitará por meio de Jesus, e [nos] apresentará juntos de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 15, 'Porque todas estas coisas são por causa de vós, para que a graça aumente por meio de muitas [pessoas] ,superabundando os agradecimentos à glória de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 16, 'Por isso não desfalecemos; mas ainda que nosso ser exterior se destrua, todavia o interior se renova a cada dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 17, 'Porque nossa leve e momentânea aflição nos produz um peso eterno de excelentíssima glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 4, 18, 'Por isso nós não prestamos atenção para as coisas visíveis, mas sim para as invisíveis; porque as coisas visíveis são temporárias, mas as invisíveis são eternas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 1, 'Porque sabemos que, se nossa casa terrestre deste tabernáculo se desfizer, temos um edifício de Deus, uma casa não feita por mãos, [mas] eterna, nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 2, 'Porque nesta [casa] gememos, desejando sermos revestidos de nossa habitação do céu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 3, 'Dado que, se estivermos vestidos, não seremos achados nus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 4, 'Pois de fato nós, os que estamos neste tabernáculo, gememos pressionados, não porque queremos ser despidos, mas sim, revestidos; para que a mortalidade seja devorada pela vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 5, 'E para isto mesmo que Deus nos preparou, ele que também deu o penhor do Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 6, 'Por isso sempre temos confiança, e sabemos que, enquanto habitarmos no corpo, estamos ausentes do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 7, '(Pois andamos pela fé, e não pela vista).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 8, 'Temos, porém, confiança, e queremos mais deixar o corpo, e habitar com o Senhor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 9, 'Por isso também desejamos muito ser agradáveis a ele, quer presentes [no nosso corpo] ,quer ausentes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 10, 'Pois todos devemos comparecer diante do Tribunal de Cristo, para que cada um receba o pagamento das coisas que fez no corpo, seja bem ou mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 11, 'Conhecendo, pois, o temor ao Senhor, persuadimos as pessoas para a fé, e a Deus somos claramente visíveis; mas espero, também, que estejamos claramente visíveis em vossas consciências.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 12, 'Porque não nos recomendamos novamente para vós; mas damos oportunidade de vos orgulhardes de nós; para que tenhais [o que responder] aos que se orgulham da aparência, e não do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 13, 'Pois se nós enlouquecemos, é para Deus; se estamos sensatos, é para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 14, 'Porque é o amor de Cristo que nos controla; pois temos certeza que, se um morreu por todos, logo todos morreram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 15, 'E ele morreu por todos, para que os que vivem não vivam mais para si, mas sim, para aquele que por eles morreu e ressuscitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 16, 'Portanto daqui em diante a ninguém conhecemos segundo a carne, e ainda que também tenhamos conhecido a Cristo segundo a carne, todavia agora não o conhecemos [assim] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 17, 'Portanto, se alguém está em Cristo, uma nova criatura [é] ; as coisas velhas já passaram, eis que tudo se fez novo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 18, 'E tudo isto [vem] de Deus, o qual por Jesus Cristo nos reconciliou consigo, e nos deu o ministério da reconciliação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 19, 'Porque Deus estava em Cristo reconciliando consigo ao mundo, não lhes atribuindo seus pecados; e pôs em nós a palavra da reconciliação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 20, 'Assim, pois, nós somos embaixadores da parte de Cristo, como se Deus rogasse por nós; [por isso] ,rogamos em Cristo: Reconciliai-vos com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 5, 21, 'Pois ele fez com que aquele que não conheceu pecado [se tornasse] pecado por nós; para que nós nele fôssemos feitos justiça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 1, 'E nós, como trabalhadores conjuntamente [com ele] , rogamos que não tenhais recebido a graça de Deus em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 2, 'Porque ele diz: Em tempo agradável te ouvi, e no dia da salvação te socorri; eis agora o tempo agradável, eis agora o dia da salvação'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 3, 'Escândalo nenhum damos em coisa alguma, para que [nosso] trabalho não seja acusado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 4, 'Mas em tudo nos fizemos agradáveis como trabalhadores de Deus, em muita tolerância, em aflições, em necessidades, em angústias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 5, 'Em açoites, em prisões, em tumultos, em trabalhos, em vigílias, em jejuns;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 6, 'Em pureza, em conhecimento, em paciência, em bondade, no Espírito Santo, em amor não fingido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 7, 'Em palavra da verdade, em poder de Deus, com armas da justiça, à esquerda, e à direita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 8, 'Por honra e por desonra; por infâmia e por boa fama; [considerados] como enganadores, e como verdadeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 9, 'Como estranhos, e conhecidos; como morrendo, e eis que estamos vivendo; como castigados e [ainda] não mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 10, 'Como entristecidos, porém sempre alegres; como pobres, porém enriquecendo a muitos; como nada tendo, e possuindo tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 11, 'Para vós, ó coríntios, está aberta nossa boca; [e] nosso coração está ampliado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 12, 'Nós não temos lhes estreitado, mas vós estais estreitos em nossos sentimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 13, 'E em recompensa disto (falo como a filhos) alargai vós também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 14, 'Não vos ajunteis em outro jugo com os descrentes. Porque, que parceria tem a justiça com injustiça? E que parceria tem a luz com as trevas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 15, 'E que acordo há entre Cristo e Belial? Ou que parte tem o crente com o incrédulo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 16, 'E que acordo há entre o Templo de Deus e os ídolos? Porque vós sois o templo do Deus vivente, como Deus disse: Neles habitarei, e entre [eles] andarei; e eu serei seu Deus, e eles serão meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 17, 'Portanto: saí do meio deles, e vos separai, diz o Senhor; e não toqueis coisa impura, e eu vos aceitarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 6, 18, 'E eu vos serei por Pai, e vós sereis para mim filhos e filhas,diz o Senhor Todo Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 1, 'Amados, por termos tais promessas, limpemo-nos de toda impureza da carne e do espírito, aperfeiçoando a santificação no temor de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 2, 'Dai lugar a nós [em vossos corações] ; contra ninguém agimos mal, a ninguém corrompemos, a ninguém abusamos para nosso proveito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 3, 'Não digo [isto] para [vos] condenar; porque já disse antes que vós estais em nossos corações, para juntamente morrermos e vivermos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 4, 'Muita confiança eu tenho em vós; eu tenho muito orgulho de vós; eu estou cheio de consolação; excedo sobremaneira de alegria em todas as nossas aflições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 5, 'Porque até quando viemos à Macedônia, nenhum repouso teve nossa carne; mas em tudo fomos afligidos: lutas por fora, temores por dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 6, 'Mas Deus, que consola aos abatidos, nos consolou com a vinda de Tito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 7, 'E não somente com a vinda dele, mas também com a consolação com que foi consolado quanto a vós, contando-nos vossas saudades, vosso choro e vosso zelo por mim, de maneira que me alegrei ainda mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 8, 'Porque, ainda que eu tenha vos entristecido com a carta, não me arrependo, ainda que tenha me causado pesar; porque vejo que aquela carta vos entristeceu, ainda que por pouco tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 9, 'Agora eu me alegro, não porque vós vos entristecestes, mas porque vos entristecestes para o arrependimento. Porque vós vos entristecestes segundo [a vontade de] Deus; de maneira que em nada sofrestes dano por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 10, 'Pois a tristeza segundo [a vontade de] Deus opera arrependimento para a salvação, de que ninguém se arrepende; mas a tristeza do mundo opera a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 11, 'Porque vede isto mesmo, quanto empenho que vossa tristeza segundo Deus produziu em vós! E também defesa [própria] , indignação, temor, saudades, zelo, e desejo de justiça! Em tudo vos mostrastes estar puros quanto a este assunto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 12, 'Portanto, ainda que tenha escrito para vós, eu não [fiz isso] por causa daquele que fez o dano, nem por causa daquele que sofreu o dano; mas sim para que nosso empenho por vós diante de Deus vos fosse revelado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 13, 'Por isso fomos consolados com vosso consolo; e muito mais nos alegramos com a alegria de Tito, de que seu espírito foi revigorado por todos vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 14, 'Porque se em alguma coisa me orgulhei de vós diante dele, não fiquei envergonhado; mas assim como falamos de vós com verdade, assim também nosso orgulho diante de Tito se confirmou verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 15, 'E os sentimentos dele por vós estão ainda maiores, por se lembrar da obediência de todos vós, de como o recebestes com temor e tremor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 7, 16, 'Por isso eu me alegro de que em tudo posso confiar em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 1, 'Também, irmãos, vos fazemos saber a graça de Deus dada às igrejas da Macedônia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 2, 'Que em muita provação de aflição, a abundância de sua alegria, e sua profunda pobreza abundaram nas riquezas de sua generosidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 3, 'Pois dou testemunho de que foram voluntários segundo [sua] capacidade e até além de [sua] capacidade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 4, 'Pedindo-nos com muito entusiasmo que aceitássemos a graça e a comunhão deste serviço para os santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 5, 'E não [somente fizeram] como nós esperávamos, mas também entregaram a si mesmos, primeiramente ao Senhor, e [depois] a nós, pela vontade de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 6, 'De maneira que convocamos a Tito para que, assim como tinha começado antes, assim também terminasse esta graça entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 7, 'Portanto, assim como em tudo abundais: em fé, em palavra, em conhecimento, em todo empenho, e em vosso amor por nós; sede também abundantes nesta graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 8, 'Eu não digo [isto] como que mandando, mas sim para também, por meio do empenho dos outros, provar a sinceridade de vosso amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 9, 'Porque já conheceis a graça de nosso Senhor Jesus Cristo, que, sendo rico, por causa de vós se fez pobre; para que com a pobreza dele, vós enriquecêsseis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 10, 'E nisto dou [minha] opinião: porque isto vos convém, não somente a fazer, mas também a querer, dado que começastes desde o ano passado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 11, 'Portanto agora completai também o que já foi começado; para que, assim como houve ânimo no querer, assim também o seja no que tendes de completar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 12, 'Porque se existe a boa vontade, [a doação] é aceitável conforme o que se tem, e não conforme o que não se tem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 13, 'Porque não [digo isto] para que outros tenham alívio, e vós opressão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 14, 'Mas [para que] igualmente, neste tempo presente, vossa abundância seja [para suprir] a falta dos outros, para que também a abundância deles seja [para suprir] vossa falta, para que haja igualdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 15, 'Como está escrito: O que muito [colhe] , não teve mais; e o que [colhe] pouco, não teve menos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 16, 'Porém graças a Deus, que ele pôs o mesmo empenho por vós no coração de Tito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 17, 'Pois aceitou [nosso] chamado, e com muito entusiasmo partiu voluntariamente até vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 18, 'E enviamos com ele o irmão que é elogiado no Evangelho por todas as igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 19, 'E não somente [isto] , mas também foi escolhido pelas igrejas como companheiro de nossa viagem com esta graça, que é administrada por nós para a glória do mesmo Senhor, e a prontidão de vosso ânimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 20, 'Assim evitamos que ninguém nos critique nesta abundância que é administrada por nós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 21, 'Procurando o que é honesto, não somente diante do Senhor, mas também diante das pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 22, 'Também enviamos com eles ao nosso irmão, ao qual muitas vezes em muitas coisas já provamos que ele é cuidadoso, e agora ainda muito mais cuidadoso pela muita confiança que [ele tem] em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 23, 'Quanto a Tito, ele é meu companheiro e cooperador para convosco; quanto a nossos irmãos, eles são representantes das igrejas, [e] glória de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 8, 24, 'Portanto, mostrai para com eles a prova de vosso amor, e de nosso orgulho por vós, diante das igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 1, 'Porque não é necessário vos escrever sobre o trabalho que se faz para os santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 2, 'Porque eu sei a prontidão de vosso ânimo, do qual eu me orgulho de vós para os Macedônios, que Acaia já está pronta desde o ano passado; e o zelo que [começou] de vós tem estimulado a muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 3, 'Porém enviei a estes irmãos, para que nosso orgulho quanto a vós neste assunto não seja vão; para que (como eu já disse) possais estar prontos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 4, 'Para que, se caso vierem [alguns] macedônios comigo, e vos encontrarem despreparados, não nos envergonhemos (para não dizermos vós), por causa da confiança neste orgulho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 5, 'Portanto achei necessário dizer a estes irmãos que viessem primeiro até vós, e preparassem primeiro vossa generosidade, já antes prometida, para que esteja pronta como boa vontade e não como avareza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 6, '[Digo] , porém isto, que o que semeia pouco, também pouco colherá; e o que semeia generosamente, também generosamente colherá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 7, 'Cada qual [faça] como propõe em [seu] coração, não com tristeza, ou por obrigação; porque Deus ama ao que dá com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 8, 'E Deus é poderoso para fazer abundar em vós toda graça, para que sempre tendo de tudo, em tudo suficientes, abundeis em toda boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 9, 'Assim como está escrito: Ele espalhou [e] deu aos pobres; sua justiça permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 10, 'Ora, aquele que dá a semente ao que semeia, também [vos] dê pão para comer, e multiplique sua sementeira, e aumente os frutos de vossa justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 11, 'Para que em tudo enriqueçais em toda generosidade, a qual opera por nós, [resultando] em graças a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 12, 'Porque o trabalho deste serviço está suprindo não somente a falta dos santos, mas também se torna abundante em muitas graças a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 13, 'Porque pela prova deste trabalho, glorificarão a Deus quanto à submissão de vossa confissão ao Evangelho de Cristo, e [da] bondade da comunhão para com eles e para com todos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 14, 'E por sua oração por vós, tendo saudades de vós, por causa da excelente graça de Deus sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 9, 15, 'E graças a Deus por seu dom indescritível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 1, 'Além disto eu mesmo, Paulo, pela mansidão e bondade de Cristo, vos rogo, (eu que em verdade sou humilde entre vós quando presente, porém ousado para convosco quando ausente);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 2, 'Rogo pois, que quando eu estiver presente, não tenha que mostrar ousadia com a confiança de que penso que terei de me mostrar ousado para com alguns que nos consideram como se andássemos segundo a carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 3, 'Pois ainda que andemos na carne, não batalhamos segundo a carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 4, 'Porque as armas de nossa batalha não são carnais, mas sim poderosas em Deus, para destruirmos fortalezas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 5, '[Assim] destruímos pensamentos e toda arrogância que se levanta contra o conhecimento de Deus, e levamos como prisioneiro todo pensamento para a obediência a Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 6, 'E estamos prontos para vingar toda desobediência, quando vossa obediência for completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 7, 'Olhais [as coisas] pela aparência? Se alguém confia de si mesmo que é de Cristo, pense o tal outra vez consigo mesmo que, assim como ele é de Cristo, assim também nós somos de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 8, 'Porque se eu também ainda mais me quiser orgulhar do nosso poder que o Senhor nos deu para edificação, e não para vossa destruição, não me envergonharei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 9, 'Para que não pareça que eu [queira] vos amedrontar por meio de cartas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 10, 'Porque eles dizem que as cartas são em verdade graves e fortes, mas a presença do corpo é fraca, e a palavra desprezível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 11, 'Pense isto o tal, que assim como somos na palavra por cartas quando ausentes, assim também [seremos] por obra quando [estivermos] presentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 12, 'Porque não ousamos a nos classificar ou comparar com alguns que louvam a si mesmos; mas estes tem falta de entendimento ao medirem a si mesmos consigo mesmos, e ao compararem a si mesmos consigo mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 13, 'Nós, porém, não nos orgulharemos além da medida, mas sim conforme a medida da extensão que Deus repartiu conosco, medida que também vos alcança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 14, 'Porque em nada estendemos além do que devíamos, como se não tivéssemos vos alcançado; pois fomos nós os primeiros a vir até vós no Evangelho de Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 15, 'Não nos orgulhamos além da medida no trabalho de outros, mas temos esperança de que, quando vossa fé crescer, seremos engrandecidos abundantemente entre vós conforme nossa extensão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 16, 'Para pregarmos o evangelho em outros [lugares] além de vós; [e] não na extensão de outros [pregadores] , para nos orgulharmos de coisas que já estavam prontas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 17, 'Porém o que se orgulha, se orgulhe no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 10, 18, 'Porque não é o que louva a si mesmo, mas sim o que louva ao Senhor; esse é o aprovado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 1, 'Gostaria que me suportásseis um pouco em [minha] loucura; mas [ainda assim] suportai-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 2, 'Pois estou zeloso de vós com zelo de Deus, porque tenho vos preparado para [vos] apresentar [como] uma virgem pura, a um marido, isto é, a Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 3, 'Mas temo que, assim como a serpente enganou a Eva com sua astúcia, também assim em alguma maneira vossas mentes se corrompam da simplicidade que está em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 4, 'Porque se aquele que vem pregasse a outro Jesus que nós não temos pregado, ou [se] recebêsseis outro espírito que não recebestes, ou evangelho diferente do que aceitastes, certamente vós [o] aceitaríeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 5, 'Porque penso que eu em nada fui inferior aos mais excelentes apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 6, 'E se também sou rude na palavra, contudo não o sou no conhecimento; mas em tudo já estamos totalmente manifestos entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 7, 'Por acaso pequei ao humilhar a mim mesmo, para que vós fôsseis exaltados, por eu ter vos anunciado gratuitamente o Evangelho de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 8, 'Eu tomei [o que era] de outras igrejas, ao receber salário, para servir a vós; e quando eu estava presente convosco, e tendo necessidade, a ninguém [incomodei] com algum encargo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 9, 'Porque os irmãos que vieram da Macedônia supriram minha falta; e em tudo eu me guardei de vos ser incômodo, e [ainda me] guardarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 47, '2 Coríntios', '2Co', 11, 10, 'A verdade de Cristo está em mim, [de modo] que este meu orgulho não me será impedido nas regiões da Acaia.')
